$genres$::jsonb);

  raise notice '0189: %', receipt;

  if coalesce(receipt ->> 'published', 'false') <> 'true' then
    raise exception '0189: nothing was published — receipt %', receipt;
  end if;

  minted := (receipt ->> 'minted')::integer;
  linked := (receipt ->> 'linked')::integer;
  if minted + linked <> 56 then
    raise exception '0189: expected 56 genres accounted for, got % minted + % linked',
      minted, linked;
  end if;

  -- **No floating nodes.** A minted genre with no `broader` edge blocks as null
  -- and its children land under "Other", which is the defect this exists to
  -- remove rather than to relocate.
  select count(*) into floating
    from ontology.concepts c
    join ontology.versions v on v.status = 'published'
    join ontology.concept_revisions r
      on r.concept_id = c.id and r.ontology_version_id = v.id and r.status = 'active'
   where c.concept_key like 'genre:apple_%'
     and not exists (
       select 1 from ontology.concept_edges e
        where e.subject_concept_id = c.id
          and e.ontology_version_id = v.id
          and e.predicate_key = 'broader'
          and e.status = 'active');
  if floating <> 0 then
    raise exception '0189: % minted genre(s) have no parent', floating;
  end if;

  -- The four the owner asked about, and the two that were the whole point:
  -- every one must now be reachable from a stated genre string.
  select count(*) into missing
    from (values ('afrobeats'), ('bollywood'), ('indian pop'), ('j pop'),
                 ('mandopop'), ('k pop'), ('latin'), ('indie rock')) as wanted(normalized)
   where not exists (
     select 1
       from ontology.concept_labels l
       join ontology.versions v on v.id = l.ontology_version_id and v.status = 'published'
       join ontology.concept_revisions r
         on r.ontology_version_id = v.id and r.concept_id = l.concept_id
      where l.normalized_label = wanted.normalized
        and l.status = 'active' and r.status = 'active'
        and r.concept_kind = 'genre');
  if missing <> 0 then
    raise exception '0189: % of the named genres still resolve to nothing', missing;
  end if;
end;
$$;

